#!/bin/bash
# Run from: projects/storage-brain/
# Implements Phases 2–5 of the Lumitra Cloud roadmap

claude --dangerously-skip-permissions \
  --agents '{
  "s3-adapter": {
    "description": "Creates S3StorageAdapter implementing StorageAdapter interface",
    "prompt": "Create packages/api/src/adapters/storage/s3.ts — an S3StorageAdapter class that implements the StorageAdapter interface from @storage-brain/shared.\n\nRead these files first for context:\n- packages/shared/src/storage-adapter.ts (the interface)\n- packages/api/src/adapters/storage/r2.ts (reference implementation)\n- packages/api/package.json (current deps)\n\nImplementation:\n1. Use @aws-sdk/client-s3 (S3Client, PutObjectCommand, GetObjectCommand, DeleteObjectCommand, HeadObjectCommand) and @aws-sdk/s3-request-presigner (getSignedUrl)\n2. Constructor takes { bucket: string, region: string, endpoint?: string, credentials: { accessKeyId: string, secretAccessKey: string }, forcePathStyle?: boolean }\n3. forcePathStyle defaults to true when endpoint is set (needed for MinIO)\n4. Implement all StorageAdapter methods: put, get, delete, exists, head\n5. Also implement getPresignedUploadUrl and getPresignedDownloadUrl using @aws-sdk/s3-request-presigner\n6. put() should convert ReadableStream to Buffer if needed before passing to PutObjectCommand\n7. get() should return { body: response.Body as ReadableStream, contentType, size, etag }\n8. Add @aws-sdk/client-s3 and @aws-sdk/s3-request-presigner to packages/api/package.json dependencies\n9. Run cd packages/api && pnpm install after updating package.json\n10. Run pnpm typecheck from the repo root to verify"
  },
  "postgres-adapter": {
    "description": "Creates PostgresDatabaseAdapter implementing DatabaseAdapter interface",
    "prompt": "Create packages/api/src/adapters/database/postgres.ts — a PostgresDatabaseAdapter class that implements the DatabaseAdapter interface from @storage-brain/shared.\n\nRead these files first for context:\n- packages/shared/src/database-adapter.ts (the interface — all method signatures)\n- packages/shared/src/types.ts (Tenant, StoredFile, Workspace, UploadSession types)\n- packages/shared/src/constants.ts (AllowedMimeType, ProcessingStatus, UploadSessionStatus)\n- packages/api/src/adapters/database/d1.ts (reference implementation — copy all SQL and row mapping logic)\n- packages/api/package.json (current deps)\n\nImplementation:\n1. Use the postgres package (porsager/postgres — lightweight, zero-dep): import postgres from 'postgres'\n2. Constructor takes { connectionString: string } and creates a sql client: this.sql = postgres(connectionString)\n3. Port EVERY method from D1DatabaseAdapter, translating D1 API to postgres:\n   - D1: db.prepare('SELECT...').bind(a,b).first() → postgres: sql`SELECT... WHERE x=${a} AND y=${b}`.then(rows => rows[0])\n   - D1: db.prepare('...').bind(...).all() → postgres: sql`...`\n   - D1: db.prepare('...').bind(...).run() → postgres: sql`...`\n   - D1 result.meta.changes → postgres: result.count\n   - Use tagged template literals for parameterized queries (postgres package style)\n4. Row mapping: Postgres returns camelCase if you use the transform option, OR map snake_case like D1 adapter does. Use the transform option: postgres(url, { transform: postgres.camel }) — this auto-converts snake_case columns to camelCase. Then adjust mappers.\n   Actually, simpler: keep the same row mappers as D1 (they expect snake_case) and dont use transform.\n5. getTenantByApiKey: same loop-all-tenants-and-verify approach as D1 adapter. Import verifyApiKey from ../../utils/crypto\n6. migrate() method: reads and executes the SQL migration file at ../migrations/001_init.sql using this.sql.file() or this.sql.unsafe()\n7. Add a close() method: await this.sql.end() for graceful shutdown\n8. Add postgres (the npm package by porsager) to packages/api/package.json dependencies\n9. Also create packages/api/src/migrations/001_init.sql — combine the two D1 migration files (migrations/0001_initial_schema.sql + migrations/0002_workspaces.sql) into one Postgres-compatible migration. Key differences from D1:\n   - Use BIGINT instead of INTEGER for byte sizes\n   - Use TEXT for JSON columns (same as D1)\n   - Use BIGINT for timestamps (epoch ms, same as D1)\n   - Add IF NOT EXISTS to all CREATE TABLE and CREATE INDEX\n   - The ALTER TABLE ADD COLUMN from 0002 should be inline in the CREATE TABLE\n10. Run cd packages/api && pnpm install\n11. Run pnpm typecheck from the repo root to verify"
  },
  "node-entry": {
    "description": "Creates Node.js entry point using @hono/node-server",
    "prompt": "Create packages/api/src/node.ts — the Node.js entry point for self-hosting Storage Brain.\n\nRead these files first:\n- packages/api/src/index.ts (the createApp factory and AppConfig interface)\n- packages/api/src/adapters/storage/r2.ts (to understand adapter pattern)\n- packages/api/src/adapters/database/d1.ts (to understand adapter pattern)\n- packages/api/package.json\n\nWAIT: Before writing code, check if packages/api/src/adapters/storage/s3.ts and packages/api/src/adapters/database/postgres.ts exist. If they dont exist yet, wait 30 seconds and check again. These are being created by other agents. If after 2 minutes they still dont exist, create placeholder imports and add TODO comments.\n\nImplementation:\n1. Import { serve } from @hono/node-server\n2. Import { createApp } from ./index (the factory)\n3. Import S3StorageAdapter from ./adapters/storage/s3\n4. Import PostgresDatabaseAdapter from ./adapters/database/postgres\n5. Read config from environment variables:\n   - STORAGE_ADAPTER (s3 for now, extensible later)\n   - S3_BUCKET, S3_REGION, S3_ENDPOINT (optional, for MinIO), AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY\n   - DATABASE_URL (postgres connection string)\n   - ADMIN_API_KEY\n   - URL_SIGNING_SECRET\n   - PORT (default 3000)\n6. Validate required env vars are set, throw clear errors if missing\n7. Create adapter instances\n8. Call db.migrate() to auto-run migrations on startup\n9. Call createApp({ storage, db }) and serve with @hono/node-server\n10. Add graceful shutdown handler (SIGTERM/SIGINT) that calls db.close() if it exists\n11. Log startup message: Storage Brain API listening on http://localhost:${port}\n12. Add @hono/node-server to packages/api/package.json dependencies\n13. Add a script to packages/api/package.json: \"start:node\": \"tsx src/node.ts\"\n14. Add tsx to devDependencies\n15. Run pnpm install from packages/api/\n16. Run pnpm typecheck from the repo root"
  },
  "docker": {
    "description": "Creates Dockerfile, docker-compose.yml, and self-hosting docs",
    "prompt": "Create Docker self-hosting setup for Storage Brain.\n\nRead packages/api/package.json first to understand the project structure. Read packages/api/src/node.ts if it exists (being created by another agent).\n\nCreate these files:\n\n1. packages/api/Dockerfile:\n   - Multi-stage build on node:20-alpine\n   - Stage 1 (builder): copy package.json + pnpm-lock.yaml, pnpm install --frozen-lockfile --prod, copy src/\n   - Stage 2 (runner): copy from builder, expose 3000, CMD [\"node\", \"--import\", \"tsx\", \"src/node.ts\"]\n   - Actually simpler: just use tsx directly. Or compile with tsup first. Lets use: RUN npx tsup src/node.ts --format esm --out-dir dist, then CMD node dist/node.js\n   - Wait, the project uses workspace deps (@storage-brain/shared). Better approach: build from the monorepo root.\n   - Final approach: Dockerfile at the REPO ROOT (projects/storage-brain/Dockerfile), not in packages/api/\n   - FROM node:20-alpine, RUN npm i -g pnpm, WORKDIR /app, COPY package.json pnpm-lock.yaml pnpm-workspace.yaml ./, COPY packages/ packages/, RUN pnpm install --frozen-lockfile, RUN pnpm --filter @storage-brain/shared build, EXPOSE 3000, CMD [\"pnpm\", \"--filter\", \"@storage-brain/api\", \"start:node\"]\n\n2. docker-compose.yml (at repo root projects/storage-brain/docker-compose.yml):\n   services:\n     api:\n       build: .\n       ports: [\"3000:3000\"]\n       environment:\n         - STORAGE_ADAPTER=s3\n         - S3_ENDPOINT=http://minio:9000\n         - S3_BUCKET=storage-brain\n         - S3_REGION=us-east-1\n         - AWS_ACCESS_KEY_ID=minioadmin\n         - AWS_SECRET_ACCESS_KEY=minioadmin\n         - DATABASE_URL=postgresql://postgres:postgres@postgres:5432/storage_brain\n         - ADMIN_API_KEY=admin-dev-key\n         - URL_SIGNING_SECRET=dev-signing-secret\n         - PORT=3000\n       depends_on:\n         postgres: { condition: service_healthy }\n         minio-setup: { condition: service_completed_successfully }\n     postgres:\n       image: postgres:16-alpine\n       environment: { POSTGRES_DB: storage_brain, POSTGRES_PASSWORD: postgres }\n       volumes: [pgdata:/var/lib/postgresql/data]\n       healthcheck: { test: pg_isready -U postgres, interval: 2s, retries: 10 }\n     minio:\n       image: minio/minio\n       command: server /data --console-address :9001\n       environment: { MINIO_ROOT_USER: minioadmin, MINIO_ROOT_PASSWORD: minioadmin }\n       volumes: [miniodata:/data]\n       ports: [\"9001:9001\"]\n     minio-setup:\n       image: minio/mc\n       depends_on: [minio]\n       entrypoint: sh -c \"mc alias set local http://minio:9000 minioadmin minioadmin && mc mb --ignore-existing local/storage-brain\"\n   volumes: { pgdata: {}, miniodata: {} }\n\n3. docs/self-hosting.md — brief guide:\n   - Prerequisites (Docker, Docker Compose)\n   - Quick start: git clone, docker compose up\n   - Create a tenant: curl -X POST http://localhost:3000/api/v1/admin/tenants -H 'Authorization: Bearer admin-dev-key' -H 'Content-Type: application/json' -d '{\"name\":\"my-tenant\"}'\n   - Environment variable reference table\n   - Production tips (use real secrets, external Postgres, S3 instead of MinIO)"
  },
  "landing-scaffold": {
    "description": "Scaffolds Lumitra Cloud Next.js project",
    "prompt": "Create the Lumitra Cloud project at projects/lumitra-cloud/ — a Next.js app for cloud.lumitra.co.\n\nFirst read the receipt-ocr-app for reference patterns:\n- projects/receipt-ocr-app/package.json (deps and scripts)\n- projects/receipt-ocr-app/wrangler.jsonc (CF Workers config)\n- projects/receipt-ocr-app/next.config.ts\n- projects/receipt-ocr-app/open-next.config.ts\n- projects/receipt-ocr-app/postcss.config.mjs\n- projects/receipt-ocr-app/tsconfig.json\n- projects/receipt-ocr-app/src/app/globals.css (design system)\n- projects/receipt-ocr-app/src/app/layout.tsx\n\nCreate the project scaffold:\n1. mkdir -p projects/lumitra-cloud/src/app\n2. package.json — same pattern as receipt-ocr-app:\n   - name: lumitra-cloud\n   - Scripts: dev, build, preview (opennextjs-cloudflare), deploy (opennextjs-cloudflare)\n   - Dependencies: next@^16, react@^19, react-dom@^19, @opennextjs/cloudflare@^1\n   - DevDependencies: typescript@^5, @types/react, @types/node, @tailwindcss/postcss@^4, tailwindcss@^4, wrangler\n3. tsconfig.json — same as receipt-ocr-app (target ES2017, moduleResolution bundler, paths @/* → ./src/*)\n4. next.config.ts — minimal: const nextConfig: NextConfig = {}; export default nextConfig;\n5. open-next.config.ts — same as receipt-ocr-app: import { defineCloudflareConfig } from '@opennextjs/cloudflare'; export default defineCloudflareConfig({});\n6. postcss.config.mjs — same as receipt-ocr-app\n7. wrangler.jsonc — name: lumitra-cloud, main: .open-next/worker.js, compatibility_date: 2025-12-30, compatibility_flags: [nodejs_compat], assets: { directory: .open-next/assets, binding: ASSETS }, routes: [{ pattern: cloud.lumitra.co, custom_domain: true }]\n8. .gitignore: node_modules, .next, .open-next, dist\n9. Run: cd projects/lumitra-cloud && pnpm install\n\nDo NOT create the landing page content yet — that is handled by the landing-page agent."
  },
  "landing-page": {
    "description": "Creates the Lumitra Cloud landing page design and content",
    "prompt": "Create the landing page for Lumitra Cloud at projects/lumitra-cloud/.\n\nWAIT: First check if projects/lumitra-cloud/package.json exists. If not, wait 30 seconds and check again (the scaffold is being created by another agent). Repeat up to 3 times.\n\nFirst read the receipt-ocr-app design system for reference:\n- projects/receipt-ocr-app/src/app/globals.css (full design system — colors, glass panels, aurora background)\n- projects/receipt-ocr-app/src/app/layout.tsx\n- projects/receipt-ocr-app/src/app/page.tsx (landing page structure)\n\nCreate these files:\n\n1. src/app/globals.css — Copy and adapt the receipt-ocr-app design system:\n   - Same dark theme: --background: #0a0a0f, --foreground: #e8e6e3\n   - Change accent from gold to a blue/purple: --accent: #6366f1 (indigo), --accent-hover: #818cf8\n   - Add a secondary accent: --accent-secondary: #06b6d4 (cyan) for Data Brain\n   - Keep the glass panel system (.glass-panel, .glass-nav)\n   - Keep the aurora background but shift colors to indigo/cyan/purple\n   - Import Geist fonts via @import url from Google Fonts\n\n2. src/app/layout.tsx — Root layout:\n   - Import globals.css\n   - Metadata: title 'Lumitra Cloud — Backend for Files & Data', description\n   - Load Geist Sans + Geist Mono fonts via next/font/google\n   - Body with font variables, antialiased, min-h-screen\n\n3. src/app/page.tsx — Landing page with these sections:\n\n   a) NAVIGATION — Sticky glass nav:\n      - Left: Lumitra Cloud logo/wordmark\n      - Right: Docs, GitHub, Pricing (anchor), Get Started (CTA button)\n\n   b) HERO — Full viewport:\n      - Title: 'Your Backend for Files & Data'\n      - Subtitle: 'Managed storage and structured data APIs. Self-host for free or let us handle everything.'\n      - Two CTAs: 'Get Started' (primary, accent bg) + 'Self-Host' (secondary, outline)\n      - Below: code snippet showing SDK usage:\n        const sb = new StorageBrain({ apiKey: 'sk_live_...' });\n        const { fileId, presignedUrl } = await sb.requestUpload({ fileName: 'photo.jpg', fileType: 'image/jpeg' });\n\n   c) PRODUCTS — Two large glass cards side by side:\n      - Storage Brain card (indigo accent):\n        - Icon: cloud/upload icon (use emoji or SVG)\n        - 'Storage Brain'\n        - 'File storage API with presigned uploads, quota management, workspaces, and webhooks.'\n        - Features list: Presigned URLs, Quota Management, Workspaces, Webhooks, Multi-provider (R2, S3, GCS)\n      - Data Brain card (cyan accent):\n        - Icon: database icon\n        - 'Data Brain'\n        - 'Structured data API — tables, columns, rows, views, and real-time queries.'\n        - Features list: Dynamic Tables, Typed Columns, Row CRUD, Views & Filters, Full SDK\n\n   d) FEATURES GRID — 3x2 grid of glass panels:\n      - 'TypeScript SDKs' — npm install @marlinjai/storage-brain-sdk\n      - 'Self-Hostable' — Deploy on your own infrastructure with Docker\n      - 'Edge-Native' — Built on Cloudflare Workers for global low latency\n      - 'Multi-Provider' — R2, S3, MinIO, GCS — bring your own storage\n      - 'Multi-Tenant' — Built-in tenant isolation, API keys, quotas\n      - 'Open Source' — MIT licensed, inspect and extend the code\n\n   e) PRICING — 3-column pricing table:\n      - Self-Hosted (Free): Full API + SDK, your infra, community support\n      - Cloud Pro ($9/mo): 50GB storage, 100GB bandwidth, managed infra, priority support\n      - Cloud Team ($29/mo): 500GB storage, 1TB bandwidth, BYOS, team management\n      - Each card is a glass panel. Highlight Pro as recommended.\n\n   f) SELF-HOST CTA — Section:\n      - 'Self-host in 3 commands'\n      - Code block: git clone ... && cd storage-brain && docker compose up\n      - Link to docs\n\n   g) FOOTER:\n      - Columns: Products (Storage Brain, Data Brain), Resources (Docs, GitHub, npm), Company (About)\n      - Bottom: © 2026 Lumitra\n\n   Style everything with Tailwind utilities + CSS custom properties (var(--accent), etc). Use the glass-panel class for cards. Keep the same hover:scale-[1.01] effect."
  }
}' \
  "Implement phases 2-5 of the Lumitra Cloud roadmap. Phase 1 (adapter extraction) is already done. The agents above handle specific pieces. Work autonomously — read the existing code, create the new files, install dependencies, and verify with typecheck. Do NOT modify any existing files that are already working unless necessary to add new exports or dependencies."
